/*
 * A328568  Irregular triangle read by rows; for n >= 0, the n-th row
 *          corresponds to the elements of the set {(n-k) XOR k, k = 0..n}, in
 *          ascending order (where XOR denotes the bitwise XOR operator).
 * https://oeis.org/A328568
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, look, base
 * Formula:   a(n) is the n-th element of the flattened ascending‑sorted set *
 *            generated by rows r ≥ 0, where row r contains the distinct
 *            values * (r‑k) XOR k for k = 0..r, sorted increasingly
 * Range:     u8 n <= 3288, u16 n <= 9851, u32 n <= 9851, u64 n <= 9851,
 *            u128 n <= 9851, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static seq_t *cache = NULL;
static size_t cache_len = 0;
static size_t cache_cap = 0;
static idx_t next_row = 0;

static void grow_cache(size_t need)
{
    if (need <= cache_cap) return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    while (new_cap < need) new_cap *= 2;
    cache = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    cache_cap = new_cap;
}

seq_t a(idx_t n)
{
    while (cache_len <= (size_t)n) {
        idx_t row = next_row++;
        size_t flag_size = (size_t)(2 * row + 1);   /* max value ≤ 2*row */
        uint8_t *present = (uint8_t *)calloc(flag_size, 1);
        if (!present) return (seq_t)0;              /* OOM fallback */

        for (size_t i = 0; i <= (size_t)row; ++i) {
            idx_t k = (idx_t)i;
            seq_t val = ((seq_t)(row - k)) ^ (seq_t)k;
            present[(size_t)val] = 1;
        }

        size_t distinct = 0;
        for (size_t v = 0; v < flag_size; ++v)
            if (present[v]) ++distinct;

        grow_cache(cache_len + distinct);

        for (size_t v = 0; v < flag_size; ++v)
            if (present[v])
                cache[cache_len++] = (seq_t)v;

        free(present);
    }
    return cache[(size_t)n];
}
